draw((cos(2*pi*i/6),sin(2*pi*i/6))--(cos(2*pi*(i+1)/6),sin(2*pi*(i+1)/6)));

draw((0,0)--(cos(2*pi*i/6),sin(2*pi*i/6)));

}
draw(circle((0,0),1));[/asy]

